{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_availability",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Dana Reyes, next_week"
    },
    {
      "id": "get_sam_availability",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Sam Okafor, next_week"
    },
    {
      "id": "get_dana_contacts",
      "kind": "lookup_via_agent",
      "agent": "contacts",
      "find": "Dana Reyes"
    },
    {
      "id": "get_sam_contacts",
      "kind": "lookup_via_agent",
      "agent": "contacts",
      "find": "Sam Okafor"
    },
    {
      "id": "generate_candidate_slots",
      "kind": "write",
      "instruction": "Generate a list of 10 potential one-hour time slots next week (Monday to Friday, 9 AM to 5 PM) that are not in the provided busy lists.",
      "max_words": 50
    },
    {
      "id": "check_dana_free",
      "kind": "check_coverage",
      "rule": "For each candidate slot, verify it does not overlap with any event in get_dana_availability"
    },
    {
      "id": "check_sam_free",
      "kind": "check_coverage",
      "rule": "For each candidate slot, verify it does not overlap with any event in get_sam_availability"
    },
    {
      "id": "find_common_slot",
      "kind": "write",
      "instruction": "Select the first time slot that passed both availability checks. If none, return 'No common slot found'.",
      "max_words": 20
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite message proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 100
    },
    {
      "id": "send_proposal",
      "kind": "lookup_via_agent",
      "agent": "mail",
      "find": "Send draft_proposal to get_dana_contacts and get_sam_contacts"
    },
    {
      "id": "verify_proposal_sent",
      "kind": "check_coverage",
      "rule": "Verify that the proposal was successfully sent to both contacts"
    }
  ],
  "output": "verify_proposal_sent"
}

{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Dana Reyes AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "get_sam_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Sam Okafor AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "generate_candidate_slots",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=system AND date >= next_monday AND date <= next_sunday AND duration=1h"
    },
    {
      "id": "batch_slots",
      "kind": "batch",
      "over": "generate_candidate_slots",
      "size": 1
    },
    {
      "id": "check_dana_free",
      "kind": "loop_over_items",
      "over": "batch_slots",
      "steps": [
        {
          "id": "check_dana_conflict",
          "kind": "check_coverage",
          "rule": "slot_start not in get_dana_calendar AND slot_end not in get_dana_calendar"
        }
      ],
      "output": "dana_free_slots"
    },
    {
      "id": "check_sam_free",
      "kind": "loop_over_items",
      "over": "dana_free_slots",
      "steps": [
        {
          "id": "check_sam_conflict",
          "kind": "check_coverage",
          "rule": "slot_start not in get_sam_calendar AND slot_end not in get_sam_calendar"
        }
      ],
      "output": "shared_free_slots"
    },
    {
      "id": "select_slot",
      "kind": "check_coverage",
      "rule": "select first item from shared_free_slots"
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite message proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 50
    },
    {
      "id": "send_to_dana",
      "kind": "lookup_via_agent",
      "agent": "mail",
      "find": "send message to Dana Reyes"
    },
    {
      "id": "send_to_sam",
      "kind": "lookup_via_agent",
      "agent": "mail",
      "find": "send message to Sam Okafor"
    }
  ],
  "output": "send_to_sam"
}
